/**
 * @file
 * Provides a system to get and store data in the browser.
 */

import { isValidType, isValidInstance } from "./validate.js";

/**
 * Class representing a storage system.
 */
class StorageManager {
  /**
   * The scope of the storage.
   *
   * @protected
   *
   * @type {string}
   */
  _scope;

  /**
   * The type of storage.
   *
   * @protected
   *
   * @type {string}
   */
  _type = "_default";

  /**
   * The storage object.
   *
   * @protected
   *
   * @type {object}
   */
  _storage = {};

  /**
   * A flag to replace existing storage in the same scope.
   *
   * @protected
   *
   * @type {boolean}
   */
  _crush = false;

  /**
   * Constructs a new `StorageManager`.
   *
   * @param {object}  [options = {}]              - The options for the storage.
   * @param {string}  options.scope               - The scope of the storage.
   * @param {?string} [options.type = null]       - The type of storage.
   * @param {boolean} [options.crush = false]     - A flag to replace existing storage in the same scope.
   * @param {boolean} [options.initialize = true] - Whether to initialize the storage.
   */
  constructor({ scope, type = null, crush = false, initialize = true } = {}) {
    this._scope = scope;
    this._type = type || "_default";
    this._crush = crush;

    if (initialize) {
      this.initialize();
    }
  }

  /**
   * Initialize the storage.
   */
  initialize() {
    // Reuse existing storage in the same scope unless crush is true.
    try {
      if (!this._crush && typeof window[this.scope] !== "undefined") {
        if (
          isValidInstance(
            StorageManager,
            { storage: window[this.scope] },
            { shouldThrow: false }
          ).status ||
          (typeof window[this.scope].storage !== "undefined" &&
            typeof window[this.scope].scope !== "undefined" &&
            typeof window[this.scope].type !== "undefined")
        ) {
          this._storage = window[this.scope].storage;
        }
      }
    } catch {
      // Do nothing.
    } finally {
      window[this.scope] = this;
    }
  }

  /**
   * The scope of the storage.
   *
   * @readonly
   *
   * @type {string}
   *
   * @see _scope
   */
  get scope() {
    return this._scope;
  }

  /**
   * The type of storage.
   *
   * @type {string}
   *
   * @see _type
   */
  get type() {
    return this._type;
  }

  set type(type) {
    if (isValidType("string", { type })) {
      this._type = type;
    }
  }

  /**
   * The storage object.
   *
   * @readonly
   *
   * @type {object}
   *
   * @see _storage
   */
  get storage() {
    return this._storage;
  }

  /**
   * Get the storage object.
   *
   * @param  {object}  [options = {}]             - The options for getting the storage.
   * @param  {string}  [options.type = this.type] - The type of storage to get.
   * @param  {?string} [options.key = null]       - The key to get the value from.
   * @return {object}                             - The storage object.
   */
  get({ type = this.type, key = null } = {}) {
    const typeCheck = isValidType("string", { type }, { shouldThrow: false });

    if (!typeCheck.status) {
      throw typeCheck.errors[0];
    }

    if (!this.storage[type]) {
      throw new Error(
        `StorageManager (${this.scope}): Type "${type}" is not initialized.`
      );
    }

    if (key !== null) {
      const keyCheck = isValidType("string", { key }, { shouldThrow: false });

      if (!keyCheck.status) {
        throw keyCheck.errors[0];
      }

      return this.storage[type][key];
    }

    return this.storage[type];
  }

  /**
   * Set the storage object.
   *
   * @param {object}  [options = {}]             - The options for setting the storage.
   * @param {string}  [options.type = this.type] - The type of storage to set.
   * @param {?string} [options.key = null]       - The key to set the value to.
   * @param {object}  [options.data = {}]        - The data to set.
   */
  set({ type = this.type, key = null, data = {} } = {}) {
    const typeCheck = isValidType("string", { type }, { shouldThrow: false });
    const dataCheck = isValidType("object", { data }, { shouldThrow: false });

    if (!typeCheck.status) {
      throw typeCheck.errors[0];
    }

    if (!dataCheck.status) {
      throw dataCheck.errors[0];
    }

    if (key !== null) {
      const keyCheck = isValidType("string", { key }, { shouldThrow: false });

      if (!keyCheck.status) {
        throw keyCheck.errors[0];
      }

      if (!this._storage[type]) {
        this._storage[type] = {};
      }

      this._storage[type][key] = data;
    } else {
      this._storage[type] = data;
    }
  }

  /**
   * Remove a value from the storage object.
   *
   * @param {object}  [options = {}]             - The options for removing from storage.
   * @param {string}  [options.type = this.type] - The type of storage to remove from.
   * @param {?string} [options.key = null]       - The key to remove the value from.
   */
  clear({ type = this.type, key = null } = {}) {
    const typeCheck = isValidType("string", { type }, { shouldThrow: false });

    if (!typeCheck.status) {
      throw typeCheck.errors[0];
    }

    if (key !== null) {
      const keyCheck = isValidType("string", { key }, { shouldThrow: false });

      if (!keyCheck.status) {
        throw keyCheck.errors[0];
      }

      delete this.storage[type][key];
    } else {
      delete this.storage[type];
    }
  }

  dispose() {
    if (typeof window !== "undefined" && window[this.scope] === this) {
      delete window[this.scope];
    }

    delete this._storage;
  }
}

export default StorageManager;
